            }
        }
        $findings = [];
        foreach ($rules as $rule) {
            if (!$evaluator->accepts($rule, $document)) {
                $findings[] = $evaluator->finding($rule, $repair);
            }
        }
        return new Plan($findings, $changed ? [new FileChange($file->file->path, $original, $document->encode())] : [], $findings);
    }
}
